import subprocess, tempfile, pathlib, os
def runfile(args, outpath):
    p=subprocess.run(["/workspace/executable"]+args,capture_output=True,timeout=5)
    return pathlib.Path(outpath).read_text() if os.path.exists(outpath) else "missing"
with tempfile.TemporaryDirectory() as d:
    f=d+"/a.txt"
    pathlib.Path(f).write_text("hello, test@example.com, with \"quotes\"\nsecond line\n")
    for X in [False,True]:
        for D in [False,True]:
            for L in [False,True]:
                for C in [False,True]:
                    outpath=d+"/o.csv"
                    if os.path.exists(outpath): os.remove(outpath)
                    args=["-f",f,"-e","-S","-o",outpath]
                    if X: args.append("-X")
                    if D: args.append("-D")
                    if L: args.append("-l")
                    if C: args.append("-C")
                    content=runfile(args,outpath)
                    print(f"X={X} D={D} L={L} C={C} -> {content!r}")
    # csv variants suffix
    for name in ["o.CSV","o.Csv","x.csv.txt","csv","o.csvx",".csv"]:
        outpath=d+"/"+name
        if os.path.exists(outpath): os.remove(outpath)
        subprocess.run(["/workspace/executable","-f",f,"-e","-S","-o",outpath],capture_output=True)
        print(name, repr(pathlib.Path(outpath).read_text()))
PY
"}

