fn normalize_url(url: &str) -> String {
    let mut normalized = url.trim_end_matches('/').to_lowercase();
    if let Some(stripped) = normalized.strip_prefix("https://") {
        normalized = stripped.to_string();
    } else if let Some(stripped) = normalized.strip_prefix("http://") {
        normalized = stripped.to_string();
    }
    normalized
}

fn trimmed_url(url: &str) -> String {
    url.trim_end_matches('/').to_string()
}

// ---------- HTTP fetching (libcurl FFI, behaviour modelled on observed client) ----------
type Curl = c_void;

extern "C" {
    fn curl_easy_init() -> *mut Curl;
    fn curl_easy_setopt(curl: *mut Curl, option: i32, ...) -> i32;
    fn curl_easy_perform(curl: *mut Curl) -> i32;
    fn curl_easy_getinfo(curl: *mut Curl, option: i32, ...) -> i32;
    fn curl_easy_cleanup(curl: *mut Curl);
}

extern "C" fn curl_write_callback(
    ptr: *mut std::os::raw::c_char,
    size: usize,
    nmemb: usize,
    userdata: *mut c_void,
) -> usize {
    let total = size.saturating_mul(nmemb);
    if total == 0 {
        return 0;
    }
    unsafe {
        let out = &mut *(userdata as *mut Vec<u8>);
        out.extend_from_slice(std::slice::from_raw_parts(ptr as *const u8, total));
    }
    total
}

fn canonical_status(status: i64) -> String {
    let reason = match status {
        100 => "Continue",
