struct ParsedUrl {
    display: String,
    curl_url: String,
}

fn parse_request_url(raw: &str) -> Result<ParsedUrl, String> {
    // raw is "{trimmed}/main/plugins.json"
    let trimmed_raw = raw.trim_matches(|c: char| (c as u32) <= 0x20);
    // Find scheme
    let colon_pos = match trimmed_raw.find(':') {
        Some(p) => p,
        None => return Err("builder error: relative URL without a base".to_string()),
    };
    let scheme = &trimmed_raw[..colon_pos];
    let valid_scheme = !scheme.is_empty()
        && scheme.chars().next().map(|c| c.is_ascii_alphabetic()).unwrap_or(false)
        && scheme.chars().all(|c| c.is_ascii_alphanumeric() || c == '+' || c == '-' || c == '.');
    if !valid_scheme {
        return Err("builder error: relative URL without a base".to_string());
    }
    let scheme_lower = scheme.to_lowercase();
    let rest = &trimmed_raw[colon_pos + 1..];
    if scheme_lower != "http" && scheme_lower != "https" {
        return Err(format!(
            "builder error for url ({}): URL scheme is not allowed",
            trimmed_raw
        ));
    }
    // For special schemes, leading slashes/backslashes before host are skipped by the URL parser.
    let rest_no_slashes = rest.trim_start_matches(|c| c == '/' || c == '\\');
    // host is up to first '/', '?', '#', or '\'
    let host_end = rest_no_slashes
        .find(|c| c == '/' || c == '\\' || c == '?' || c == '#')
        .unwrap_or(rest_no_slashes.len());
    let authority = &rest_no_slashes[..host_end];
    let after_authority = &rest_no_slashes[host_end..];
    // Fragment handling: everything after '#' is not part of the path.
    let path_and_query = match after_authority.find('#') {
        Some(p) => &after_authority[..p],
        None => after_authority,
    };
    // authority may contain userinfo
    let (userinfo, hostport) = match authority.rfind('@') {
        Some(p) => (Some(&authority[..p]), &authority[p + 1..]),
        None => (None, authority),
    };
    if hostport.is_empty() {
        return Err("builder error: empty host".to_string());
    }
    // IPv6 host
    let (host_display, port_str): (String, Option<String>) = if hostport.starts_with('[') {
        match hostport.find(']') {
            Some(end) => {
                let host = &hostport[..=end];
                // basic validation inside brackets must look like an IPv6 literal
                let inside = &hostport[1..end];
                if inside.is_empty() || !inside.chars().all(|c| c.is_ascii_hexdigit() || c == ':' || c == '.' || c == '%') {
                    return Err("builder error: invalid IPv6 address".to_string());
                }
                let rest_hp = &hostport[end + 1..];
                if rest_hp.is_empty() {
                    (host.to_lowercase(), None)
                } else if let Some(port) = rest_hp.strip_prefix(':') {
                    (host.to_lowercase(), Some(port.to_string()))
                } else {
                    return Err("builder error: invalid IPv6 address".to_string());
                }
            }
            None => return Err("builder error: invalid IPv6 address".to_string()),
        }
    } else {
        match hostport.rfind(':') {
            Some(p) => {
                let host = &hostport[..p];
                let port = &hostport[p + 1..];
                (host.to_lowercase(), Some(port.to_string()))
            }
            None => (hostport.to_lowercase(), None),
        }
    };
    if host_display.is_empty() {
        return Err("builder error: empty host".to_string());
    }
    // host without brackets: check for invalid characters (space / controls / etc.)
    if !host_display.starts_with('[') {
        if host_display.chars().any(|c| (c as u32) <= 0x20 || c == '%' && false) {
            return Err("builder error: invalid international domain name".to_string());
        }
        // A dotted numeric host that is not a valid IPv4 address is rejected by the URL parser.
        let looks_ipv4 = host_display.chars().all(|c| c.is_ascii_digit() || c == '.') && host_display.contains('.');
        if looks_ipv4 {
            let parts: Vec<&str> = host_display.split('.').collect();
            let valid = parts.len() == 4
                && parts.iter().all(|p| {
                    !p.is_empty()
                        && p.chars().all(|c| c.is_ascii_digit())
                        && p.parse::<u32>().map(|v| v <= 255).unwrap_or(false)
                });
            if !valid {
                return Err("builder error: invalid IPv4 address".to_string());
            }
        }
    }
    if let Some(port) = &port_str {
        if port.is_empty() || !port.chars().all(|c| c.is_ascii_digit()) {
            return Err("builder error: invalid port number".to_string());
        }
        if port.parse::<u32>().map(|v| v > 65535).unwrap_or(true) {
            return Err("builder error: invalid port number".to_string());
        }
    }
    let mut display = format!("{}://", scheme_lower);
    if let Some(ui) = userinfo {
        display.push_str(ui);
        display.push('@');
    }
    display.push_str(&host_display);
    if let Some(port) = &port_str {
        display.push(':');
        display.push_str(port);
    }
    let path = if path_and_query.is_empty() {
        "/".to_string()
    } else if path_and_query.starts_with('/') || path_and_query.starts_with('?') {
        path_and_query.to_string()
    } else {
        format!("/{}", path_and_query)
    };
    display.push_str(&path);
    Ok(ParsedUrl {
        curl_url: display.clone(),
        display,
    })
}

fn fetch_url(url: &str) -> Result<(i64, Vec<u8>), String> {
    let parsed = parse_request_url(url)?;
    let display = parsed.display.clone();
    let c_url = std::ffi::CString::new(parsed.curl_url.clone()).map_err(|_| "builder error: relative URL without a base".to_string())?;
    let ua = std::ffi::CString::new("Mozilla/5.0 (Windows NT 6.3; WOW64; Trident/7.0; Touch; MAGWJS; rv:11.0) like Gecko").unwrap();
    let mut body: Vec<u8> = Vec::new();
    let mut err_buf = vec![0u8; 256];
    unsafe {
        let curl = curl_easy_init();
        if curl.is_null() {
            return Err(format!(
                "error sending request for url ({}): error trying to connect: Connection refused (os error 111)",
                display
            ));
        }
        curl_easy_setopt(curl, 10002, c_url.as_ptr()); // URL
        curl_easy_setopt(curl, 10018, ua.as_ptr()); // USERAGENT
        curl_easy_setopt(curl, 20011, curl_write_callback as usize); // WRITEFUNCTION
        curl_easy_setopt(curl, 10001, &mut body as *mut Vec<u8> as *mut c_void); // WRITEDATA
        curl_easy_setopt(curl, 52, 0i64); // FOLLOWLOCATION = false
        curl_easy_setopt(curl, 10010, err_buf.as_mut_ptr() as *mut std::os::raw::c_char); // ERRORBUFFER
        curl_easy_setopt(curl, 179, 1i64); // NOSIGNAL
        let code = curl_easy_perform(curl);
        if code != 0 {
            let cstr = std::ffi::CStr::from_bytes_until_nul(&err_buf).unwrap_or(std::ffi::CStr::from_bytes_with_nul(b"\0").unwrap());
            let msg = cstr.to_string_lossy().to_string();
            curl_easy_cleanup(curl);
            let reason = match code {
                6 => "error trying to connect: dns error: failed to lookup address information: Temporary failure in name resolution".to_string(),
                7 => {
                    if msg.contains("Connection refused") {
                        "error trying to connect: tcp connect error: Connection refused (os error 111)".to_string()
                    } else if msg.contains("Network is unreachable") || msg.contains("Network unreachable") {
                        "error trying to connect: tcp connect error: Network is unreachable (os error 101)".to_string()
                    } else if msg.contains("timed out") || msg.contains("Timed out") {
                        "error trying to connect: tcp connect error: Connection timed out (os error 110)".to_string()
                    } else {
                        format!("error trying to connect: tcp connect error: {}", msg)
                    }
                }
                35 | 60 | 77 | 51 | 58 => {
                    if msg.to_lowercase().contains("self signed") || msg.to_lowercase().contains("self-signed") {
                        "error trying to connect: error:0A000086:SSL routines:tls_post_process_server_certificate:certificate verify failed:../ssl/statem/statem_clnt.c:1883: (self-signed certificate)".to_string()
                    } else if code == 60 {
                        "error trying to connect: error:0A000086:SSL routines:tls_post_process_server_certificate:certificate verify failed:../ssl/statem/statem_clnt.c:1883:".to_string()
                    } else {
                        "error trying to connect: error:0A00010B:SSL routines:ssl3_get_record:wrong version number:../ssl/record/ssl3_record.c:354:".to_string()
                    }
                }
                3 => return Err("builder error: relative URL without a base".to_string()),
                _ => {
                    // Strip curl's generic prefixes for a closer match to the observed client.
                    let mut m = msg.clone();
                    if m.is_empty() {
                        m = format!("curl error {}", code);
                    }
                    format!("error trying to connect: {}", m)
                }
            };
            return Err(format!(
                "error sending request for url ({}): {}",
                display, reason
            ));
        }
        let mut status: i64 = 0;
        curl_easy_getinfo(curl, 2097154, &mut status as *mut i64); // CURLINFO_RESPONSE_CODE
        curl_easy_cleanup(curl);
        Ok((status, body))
    }
}

pub fn download_plugins(url: &str) -> Vec<Plugin> {
    let trimmed = trimmed_url(url);
    let request_url = format!("{}/main/plugins.json", trimmed);
    match fetch_url(&request_url) {
        Ok((status, body)) => {
            if !(200..300).contains(&status) {
                println!(
                    "Error: Received a {} status code from the server.",
                    canonical_status(status)
                );
                process::exit(1);
            }
            let text = String::from_utf8_lossy(&body).to_string();
            match serde_json::from_str::<Vec<Plugin>>(&text) {
                Ok(plugins) => plugins,
                Err(e) => {
                    eprintln!(
                        "[-] Error: Failed to parse plugins.json from the provided URL. Reason: {}",
                        e
                    );
                    process::exit(1);
                }
            }
        }
        Err(e) => {
            eprintln!(
                "[-] Error: Failed to parse plugins.json from the provided URL. Reason: {}",
                e
            );
            process::exit(1);
        }
    }
}

fn print_duplicate_messages_and_check_single(downloaded: &[Plugin], existing: &[Plugin]) -> bool {
    // Returns true if processing should abort (single downloaded plugin that is a duplicate).
    if downloaded.len() == 1 {
        if existing.iter().any(|e| e.arg_long_name == downloaded[0].arg_long_name) {
            println!(
                "[-] Error: Skipping Duplicate plugin found with arg_long_name: {}",
                downloaded[0].arg_long_name
            );
            return true;
        }
        return false;
    }
    for dl in downloaded {
        for ex in existing {
            if dl.arg_long_name == ex.arg_long_name {
                println!(
                    "[-] Error: Skipping Duplicate plugin found with arg_long_name: {}",
                    dl.arg_long_name
                );
            }
        }
    }
    false
}

pub fn add_plugin(url: &str) {
    let downloaded = download_plugins(url);
    let mut existing = load_plugins();
    if print_duplicate_messages_and_check_single(&downloaded, &existing) {
        return;
    }
    let trimmed = trimmed_url(url);
    for mut plugin in downloaded {
        plugin.source_url = trimmed.clone();
        existing.push(plugin);
    }
    save_plugins(&existing);
    println!("[*] Download and added plugin: {}", url);
}

pub fn update_plugin(url: &str) -> bool {
    let mut existing = load_plugins();
    let target = normalize_url(url);
    if !existing.iter().any(|p| normalize_url(&p.source_url) == target) {
        println!(
            "[-] Error: No existing plugin found with the given URL: {}",
            url
        );
        return false;
    }
    existing.retain(|p| normalize_url(&p.source_url) != target);
    save_plugins(&existing);
    // Download and add (mirrors add, but with the already-trimmed existing list).
    let downloaded = download_plugins(url);
    if print_duplicate_messages_and_check_single(&downloaded, &existing) {
        return false;
    }
    let trimmed = trimmed_url(url);
    for mut plugin in downloaded {
        plugin.source_url = trimmed.clone();
        existing.push(plugin);
    }
    save_plugins(&existing);
    println!("[*] Updated Plugin: {}", url);
    true
}

pub fn update_all_plugins() {
    let plugins = load_plugins();
    let urls: Vec<String> = plugins.iter().map(|p| p.source_url.clone()).collect();
    for url in urls {
        if !update_plugin(&url) {
            println!("[-] Failed to Update Plugin: {}", url);
        }
    }
}

pub fn remove_plugin(url: &str) {
    let mut existing = load_plugins();
    let original_len = existing.len();
    let target = normalize_url(url);
    existing.retain(|p| normalize_url(&p.source_url) != target);
    if existing.len() != original_len {
        save_plugins(&existing);
        println!("[*] Removed plugin: {}", url);
    }
}

pub fn list_plugins() {
    let plugins = load_plugins();
    let plugin_path = get_plugin_file_path();
    if plugins.is_empty() {
        println!("No plugins found. Plugin File: {}", plugin_path);
        return;
    }
    println!("Plugin File: {}", plugin_path);
    println!();
    let headers = ["Source URL", "Version", "Argument Long Name"];
    let mut widths = [
        headers[0].chars().count(),
        headers[1].chars().count(),
        headers[2].chars().count(),
    ];
    for p in &plugins {
        widths[0] = widths[0].max(p.source_url.chars().count());
        widths[1] = widths[1].max(p.version.chars().count());
        widths[2] = widths[2].max(p.arg_long_name.chars().count());
    }
    println!(
        "{:<w0$} | {:<w1$} | {:<w2$}",
        headers[0],
        headers[1],
        headers[2],
        w0 = widths[0],
        w1 = widths[1],
        w2 = widths[2]
    );
    for p in &plugins {
        println!(
            "{:<w0$} | {:<w1$} | {:<w2$}",
            p.source_url,
            p.version,
            p.arg_long_name,
            w0 = widths[0],
            w1 = widths[1],
            w2 = widths[2]
        );
    }
}
