}

fn get_patterns(args: &Args, matches: &clap::ArgMatches, plugins_list: &[Plugin]) -> HashMap<String, Regex> {
    let all = build_all_patterns(plugins_list);
    let mut selected: HashSet<String> = HashSet::new();
    let mut any_selected = false;
    let builtin_flags: Vec<(&str, bool)> = vec![
        ("email", args.email),
        ("phone_number", args.phone),
        ("hashes", args.hash),
        ("ip_address", args.ip_addr),
        ("ipv6_address", args.ipv6_addr),
        ("mac_address", args.mac_addr),
        ("credit_card", args.credit_card),
        ("url", args.url),
        ("files", args.files),
        ("bitcoin_wallet", args.bitcoin),
        ("aws_keys", args.aws),
        ("google", args.google),
        ("srv_dns", args.dns),
        ("social_security", args.social),
    ];
    for (name, flag) in &builtin_flags {
        if *flag {
            any_selected = true;
            selected.insert(name.to_string());
        }
    }
    // Builtin argument ids, whose presence refers to the builtin rather than a plugin.
    let builtin_arg_ids: HashSet<&str> = [
        "file", "add", "update", "remove", "list", "clean", "directory", "ignore", "line",
        "thorough", "display", "suppress", "drop", "filter", "hide", "output", "time", "email",
        "phone", "hash", "ip-addr", "ipv6-addr", "mac-addr", "credit-card", "url", "files",
        "bitcoin", "aws", "google", "dns", "social", "help", "version",
    ]
    .iter()
    .cloned()
    .collect();
    let mut seen_plugin_arg: HashSet<String> = HashSet::new();
    for plugin in plugins_list {
        if builtin_arg_ids.contains(plugin.arg_long_name.as_str()) {
            continue;
        }
        if seen_plugin_arg.contains(&plugin.arg_long_name) {
            continue;
        }
        // get_flag can panic in clap if an id is somehow missing; guard by ids list.
        let is_set = matches
            .try_get_flag::<bool>(plugin.arg_long_name.clone())
            .unwrap_or(false);
        if is_set {
            any_selected = true;
            seen_plugin_arg.insert(plugin.arg_long_name.clone());
            selected.insert(plugin.content_type.clone());
        }
    }
    if !any_selected {
        return all;
    }
    let mut filtered: HashMap<String, Regex> = HashMap::new();
    for (k, v) in all.iter() {
        if selected.contains(k) {
            filtered.insert(k.clone(), v.clone());
        }
    }
    if filtered.is_empty() {
        return all;
    }
    filtered
}

fn csv_header(args: &Args) -> String {
    let mut parts: Vec<String> = Vec::new();
    if !args.hide {
        parts.push("content_type".to_string());
    }
    if args.display {
        parts.push("file".to_string());
    }
    if args.line {
        parts.push("line".to_string());
    }
    parts.push("data".to_string());
    parts.join(", ")
}

fn is_csv(output: &str) -> bool {
    output.ends_with(".csv")
}

fn write_to_output(content: &str, output_path: &str, source_file: &str, ignore: bool) {
    use std::fs::OpenOptions;
    use std::io::Write;
    let file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(output_path);
    match file {
        Ok(mut f) => {
            if let Err(e) = writeln!(f, "{}", content) {
                println!("Failed to write to output file: {} error: {}", source_file, e);
            }
        }
        Err(e) => {
            if !ignore {
                match e.kind() {
                    io::ErrorKind::NotFound => {
                        println!("[-] Failed to open output file: {}", source_file)
                    }
                    io::ErrorKind::PermissionDenied => {
                        println!("[-] Permission denied for file: {}", source_file)
                    }
                    _ => println!(
                        "[-] Failed to open output file: {}. Error: {}",
                        source_file, e
                    ),
                }
            }
            process::exit(1);
        }
    }
}

fn format_result(
    args: &Args,
    identifier: &str,
    content: &str,
    filename: &str,
    line_number: usize,
) -> String {
    if !args.output.is_empty() && is_csv(&args.output) {
        let mut parts: Vec<String> = Vec::new();
        if !args.hide {
            parts.push(identifier.to_string());
        }
        if args.display {
            parts.push(filename.to_string());
        }
        if args.line {
            parts.push(line_number.to_string());
        }
        parts.push(content.to_string());
        parts.join(", ")
    } else if args.line || args.display {
        let mut out = String::new();
        if !args.hide {
            out.push_str(identifier);
            out.push_str(", ");
        }
        if args.display {
            out.push_str("file: ");
            out.push_str(filename);
            out.push(' ');
        }
        out.push_str(content);
        if args.line {
            out.push_str(", line: ");
            out.push_str(&line_number.to_string());
        }
        out
    } else {
        let mut out = String::new();
        if !args.hide {
            out.push_str(identifier);
            out.push_str(": ");
        }
        out.push_str(content);
        out
    }
}

fn emit_result(
    args: &Args,
    identifier: &str,
    content: &str,
    filename: &str,
    line_number: usize,
) {
    let formatted = format_result(args, identifier, content, filename, line_number);
    if args.output.is_empty() {
        println!("{}", formatted);
    } else {
        write_to_output(&formatted, &args.output, filename, args.ignore);
    }
}

fn passes(content: &str, args: &Args, drop_re: &Option<Regex>, filter_re: &Option<Regex>) -> bool {
    if !args.filter.is_empty() {
        if let Some(re) = filter_re {
            if !re.is_match(content) {
                return false;
            }
        }
    }
    if !args.drop.is_empty() {
        if let Some(re) = drop_re {
            if re.is_match(content) {
                return false;
            }
        }
    }
    true
}

fn process_line(
    line: &str,
    line_number: usize,
    filename: &str,
    patterns: &HashMap<String, Regex>,
    args: &Args,
    drop_re: &Option<Regex>,
    filter_re: &Option<Regex>,
) {
    let mut unique_matches: HashSet<String> = HashSet::new();
    'outer: for (identifier, pattern) in patterns.iter() {
        for mat in pattern.find_iter(line) {
            let matched = mat.as_str();
            if args.clean {
                if passes(matched, args, drop_re, filter_re) {
                    if args.thorough {
                        if unique_matches.insert(matched.to_string()) {
                            emit_result(args, identifier, matched, filename, line_number);
                        }
                    } else {
                        emit_result(args, identifier, matched, filename, line_number);
                        break 'outer;
                    }
                }
            } else if args.thorough {
                if passes(line, args, drop_re, filter_re) {
                    emit_result(args, identifier, line, filename, line_number);
                }
                if passes(matched, args, drop_re, filter_re)
                    && unique_matches.insert(matched.to_string())
                {
                    emit_result(args, identifier, matched, filename, line_number);
                }
            } else {
                if passes(line, args, drop_re, filter_re) {
                    emit_result(args, identifier, line, filename, line_number);
                    break 'outer;
                } else if passes(matched, args, drop_re, filter_re) {
                    emit_result(args, identifier, matched, filename, line_number);
                    break 'outer;
                } else {
                    continue;
                }
            }
        }
    }
}

fn process_reader<R: BufRead>(
    reader: R,
    filename: &str,
    patterns: &HashMap<String, Regex>,
    args: &Args,
    drop_re: &Option<Regex>,
    filter_re: &Option<Regex>,
) {
    for (idx, line_result) in reader.lines().enumerate() {
        if let Ok(line) = line_result {
            process_line(&line, idx + 1, filename, patterns, args, drop_re, filter_re);
        }
    }
}

fn process_file(
    file_path: &str,
    patterns: &HashMap<String, Regex>,
    args: &Args,
    drop_re: &Option<Regex>,
    filter_re: &Option<Regex>,
) -> io::Result<()> {
    match File::open(file_path) {
        Ok(file) => {
            let reader = BufReader::new(file);
            process_reader(reader, file_path, patterns, args, drop_re, filter_re);
            Ok(())
        }
        Err(e) => {
            if !args.ignore {
                match e.kind() {
                    io::ErrorKind::NotFound => println!("[-] File not found: {}", file_path),
                    io::ErrorKind::PermissionDenied => {
                        println!("[-] Permission denied for file: {}", file_path)
                    }
                    _ => println!("[-] Error opening file: {}. Error: {}", file_path, e),
                }
            }
            Err(e)
        }
    }
}

fn process_file_path(
    path: &std::path::Path,
    patterns: &HashMap<String, Regex>,
    args: &Args,
    drop_re: &Option<Regex>,
    filter_re: &Option<Regex>,
) -> io::Result<()> {
    let display_name = path.display().to_string();
    match File::open(path) {
        Ok(file) => {
            let reader = BufReader::new(file);
            process_reader(reader, &display_name, patterns, args, drop_re, filter_re);
            Ok(())
        }
        Err(e) => {
            if !args.ignore {
                match e.kind() {
                    io::ErrorKind::NotFound => println!("[-] File not found: {}", display_name),
                    io::ErrorKind::PermissionDenied => {
                        println!("[-] Permission denied for file: {}", display_name)
                    }
                    _ => println!("[-] Error opening file: {}. Error: {}", display_name, e),
                }
            }
            Err(e)
        }
    }
}

fn main() {
    let plugins_list = plugins::load_plugins();
    let cmd = build_command(&plugins_list);
    let matches = cmd.get_matches();
    let args = Args {
        file: matches.get_one::<String>("file").cloned().unwrap_or_default(),
        add: matches.get_one::<String>("add").cloned().unwrap_or_default(),
        update: matches.get_one::<String>("update").cloned().unwrap_or_default(),
        remove: matches.get_one::<String>("remove").cloned().unwrap_or_default(),
        list: matches.get_flag("list"),
        clean: matches.get_flag("clean"),
        directory: matches.get_one::<String>("directory").cloned().unwrap_or_default(),
        ignore: matches.get_flag("ignore"),
        line: matches.get_flag("line"),
        thorough: matches.get_flag("thorough"),
        display: matches.get_flag("display"),
        suppress: matches.get_flag("suppress"),
        drop: matches.get_one::<String>("drop").cloned().unwrap_or_default(),
        filter: matches.get_one::<String>("filter").cloned().unwrap_or_default(),
        hide: matches.get_flag("hide"),
        output: matches.get_one::<String>("output").cloned().unwrap_or_default(),
        time: matches.get_flag("time"),
        email: matches.get_flag("email"),
        phone: matches.get_flag("phone"),
        hash: matches.get_flag("hash"),
        ip_addr: matches.get_flag("ip-addr"),
        ipv6_addr: matches.get_flag("ipv6-addr"),
        mac_addr: matches.get_flag("mac-addr"),
        credit_card: matches.get_flag("credit-card"),
        url: matches.get_flag("url"),
        files: matches.get_flag("files"),
        bitcoin: matches.get_flag("bitcoin"),
        aws: matches.get_flag("aws"),
        google: matches.get_flag("google"),
        dns: matches.get_flag("dns"),
        social: matches.get_flag("social"),
    };

    if args.list {
        plugins::list_plugins();
        process::exit(1);
    }
    if !args.add.is_empty() {
        plugins::add_plugin(&args.add);
        process::exit(1);
    }
    if !args.remove.is_empty() {
        plugins::remove_plugin(&args.remove);
        process::exit(1);
    }
    if !args.update.is_empty() {
        if args.update.to_lowercase() == "all" {
            plugins::update_all_plugins();
        } else {
            plugins::update_plugin(&args.update);
        }
        process::exit(1);
    }

    let start_time = Instant::now();
    // Compile --drop / --filter patterns (these unwraps intentionally mirror the original).
    let drop_re = if !args.drop.is_empty() {
        Some(Regex::new(&args.drop).unwrap())
    } else {
        None
    };
    let filter_re = if !args.filter.is_empty() {
        Some(Regex::new(&args.filter).unwrap())
    } else {
        None
    };
    let patterns = get_patterns(&args, &matches, &plugins_list);

    if !args.output.is_empty() && is_csv(&args.output) {
        let header = csv_header(&args);
        write_to_output(&header, &args.output, &args.file, args.ignore);
    }

    if !args.file.is_empty() {
        if process_file(&args.file, &patterns, &args, &drop_re, &filter_re).is_err() {
            process::exit(1);
        }
    } else if !args.directory.is_empty() {
        for entry in WalkDir::new(&args.directory) {
            if let Ok(entry) = entry {
                if entry.file_type().is_file() {
                    let _ = process_file_path(entry.path(), &patterns, &args, &drop_re, &filter_re);
                }
            }
        }
    } else {
        if !args.suppress {
            println!("[*] Reading standard input. If you meant to analyze a file use 'ds -f <FILE>' (ctrl+c to exit)");
        }
        let stdin = io::stdin();
        let reader = stdin.lock();
        process_reader(reader, &args.file, &patterns, &args, &drop_re, &filter_re);
    }

    if args.time {
        let elapsed = start_time.elapsed().as_secs();
        println!(
            "[*] Time elapsed: {:02}h:{:02}m:{:02}s",
            elapsed / 3600,
            (elapsed % 3600) / 60,
            elapsed % 60
        );
    }
}
