insert = r'''
fn punycode_adapt(mut delta: u32, num_points: u32, first_time: bool) -> u32 {
    delta = if first_time { delta / 700 } else { delta / 2 };
    delta += delta / num_points;
    let mut k = 0;
    while delta > 455 {
        delta /= 35;
        k += 36;
    }
    k + (36 * delta) / (delta + 38)
}

fn punycode_encode_label(label: &str) -> String {
    let input: Vec<char> = label.chars().collect();
    let mut output = String::new();
    for &c in &input {
        if c.is_ascii() {
            output.push(c);
        }
    }
    let basic_len = output.chars().count() as u32;
    let mut handled = basic_len;
    if basic_len > 0 && (handled as usize) < input.len() {
        output.push('-');
    }
    let mut n: u32 = 128;
    let mut delta: u32 = 0;
    let mut bias: u32 = 72;
    while (handled as usize) < input.len() {
        let mut m: u32 = u32::MAX;
        for &c in &input {
            let cp = c as u32;
            if cp >= n && cp < m {
                m = cp;
            }
        }
        if m == u32::MAX {
            break;
        }
        delta = delta.saturating_add((m - n).saturating_mul(handled + 1));
        n = m;
        for &c in &input {
            let cp = c as u32;
            if cp < n {
                delta += 1;
            } else if cp == n {
                let mut q = delta;
                let mut k: u32 = 36;
                loop {
                    let tt = if k <= bias {
                        1
                    } else if k >= bias + 26 {
                        26
                    } else {
                        k - bias
                    };
                    if q < tt {
                        break;
                    }
                    let digit = tt + (q - tt) % (36 - tt);
                    let ch = if digit < 26 {
                        (b'a' + digit as u8) as char
                    } else {
                        (b'0' + (digit - 26) as u8) as char
                    };
                    output.push(ch);
                    q = (q - tt) / (36 - tt);
                    k += 36;
                }
                let digit_ch = if q < 26 {
                    (b'a' + q as u8) as char
                } else {
                    (b'0' + (q - 26) as u8) as char
                };
                output.push(digit_ch);
                bias = punycode_adapt(delta, handled + 1, handled == basic_len);
                delta = 0;
                handled += 1;
            }
        }
        delta += 1;
        n += 1;
    }
    output
}

fn parse_ipv4_number(part: &str) -> Option<u128> {
    if part.is_empty() {
        return None;
    }
    let (radix, digits) = if part.len() >= 2 && (&part[..2] == "0x" || &part[..2] == "0X") {
        (16, &part[2..])
    } else if part.len() >= 2 && part.starts_with('0') {
        (8, &part[1..])
    } else {
        (10, part)
    };
    if digits.is_empty() {
        return Some(0);
    }
    let mut value: u128 = 0;
    for c in digits.chars() {
        let d = c.to_digit(radix)?;
        value = value.checked_mul(radix as u128)?.checked_add(d as u128)?;
        if value > (1u128 << 40) {
            // Keep a large value so the caller's range checks reject it.
            return Some(value);
        }
    }
    Some(value)
}

fn normalize_host(raw_host: &str) -> Result<String, String> {
    // Percent-decode the host first (the URL parser does this before IDNA).
    let mut decoded_bytes: Vec<u8> = Vec::new();
    let bytes = raw_host.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() {
            let hex = std::str::from_utf8(&bytes[i + 1..i + 3]).unwrap_or("");
            if let Ok(v) = u8::from_str_radix(hex, 16) {
                decoded_bytes.push(v);
                i += 3;
                continue;
            }
        }
        decoded_bytes.push(bytes[i]);
        i += 1;
    }
    let decoded = match String::from_utf8(decoded_bytes) {
        Ok(s) => s,
        Err(_) => return Err("builder error: invalid international domain name".to_string()),
    };
    let mut mapped = String::new();
    for c in decoded.chars() {
        match c {
            '\u{3002}' | '\u{FF0E}' | '\u{FF61}' => mapped.push('.'),
            '\u{FF01}'..='\u{FF5E}' => {
                mapped.push(char::from_u32((c as u32) - 0xFEE0).unwrap_or(c))
            }
            _ => mapped.push(c),
        }
    }
    let lowered: String = mapped.chars().flat_map(|c| c.to_lowercase()).collect();
    if lowered.is_empty() {
        return Err("builder error: empty host".to_string());
    }
    // IPv4 forms (including shorthand and non-decimal numbers).
    let mut labels: Vec<String> = lowered.split('.').map(|s| s.to_string()).collect();
    let mut ipv4_check_labels = labels.clone();
    if ipv4_check_labels.len() > 1 && ipv4_check_labels.last().map(|s| s.is_empty()).unwrap_or(false) {
        ipv4_check_labels.pop();
    }
    if let Some(last) = ipv4_check_labels.last() {
        if parse_ipv4_number(last).is_some() {
            if ipv4_check_labels.len() > 4 {
                return Err("builder error: invalid IPv4 address".to_string());
            }
            let mut values: Vec<u128> = Vec::new();
            for part in &ipv4_check_labels {
                match parse_ipv4_number(part) {
                    Some(v) => values.push(v),
                    None => return Err("builder error: invalid IPv4 address".to_string()),
                }
            }
            for &v in &values[..values.len().saturating_sub(1)] {
                if v > 255 {
                    return Err("builder error: invalid IPv4 address".to_string());
                }
            }
            let last_value = *values.last().unwrap();
            let max_last = 1u128 << (8 * (5 - values.len()));
            if last_value >= max_last {
                return Err("builder error: invalid IPv4 address".to_string());
            }
            let mut address: u128 = last_value;
            for (idx, &v) in values[..values.len() - 1].iter().enumerate() {
                address += v * (1u128 << (8 * (3 - idx)));
            }
            let addr = address as u32;
            return Ok(format!(
                "{}.{}.{}.{}",
                (addr >> 24) & 255,
                (addr >> 16) & 255,
                (addr >> 8) & 255,
                addr & 255
            ));
        }
    }
    // Domain labels: ASCII labels are kept; non-ASCII labels use IDNA/punycode.
    let mut out_labels: Vec<String> = Vec::new();
    for label in labels.drain(..) {
        if label.is_ascii() {
            if label
                .chars()
                .any(|c| (c as u32) < 0x20 || c == '\u{7f}' || " #%:/?@[\\]^|".contains(c))
            {
                return Err("builder error: invalid international domain name".to_string());
            }
            if label.to_lowercase().starts_with("xn--") && label.len() <= 4 {
                return Err("builder error: invalid international domain name".to_string());
            }
            out_labels.push(label);
        } else {
            if label.chars().any(|c| c.is_whitespace() || (c as u32) < 0x20) {
                return Err("builder error: invalid international domain name".to_string());
            }
            out_labels.push(format!("xn--{}", punycode_encode_label(&label)));
        }
    }
    Ok(out_labels.join("."))
}

